#!/usr/bin/env bash
# Thin wrapper around scripts/sync-flutter-client.py -- generated by CruftFree, do not edit manually.
#
# This script does no client sync work of its own. It exists so an operator can
# run the client sync from a POSIX shell without thinking about interpreters:
# it anchors the working directory at the project root, finds a usable Python
# on PATH, and hands every argument straight to scripts/sync-flutter-client.py.
#
# It creates NO virtual environment: sync-flutter-client.py is written against the
# Python standard library alone, so a venv would install nothing and could only
# add a failure mode on a machine where the venv module is unavailable or this
# tree is read-only. All client sync logic --
# every manifest check, every consumer check, every copy -- lives in that one Python
# script, so the bash and PowerShell entrypoints cannot drift apart.
set -euo pipefail

# The client sync script and this wrapper are siblings; every path the Python
# script uses is relative to the project root, so anchor there first. This
# makes 'scripts/sync-flutter-client.sh' (from the project root) and './sync-flutter-client.sh'
# (from inside its own folder) behave identically.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$PROJECT_ROOT"

# Interpreter that runs the client sync directly -- there is no venv to create,
# so this is the one Python this wrapper needs.
find_usable_python() {
  local candidate
  for candidate in python3 python; do
    if command -v "$candidate" >/dev/null 2>&1; then
      # Reject a Windows App Execution Alias stub (a zero-byte shim that opens
      # the Microsoft Store instead of running Python) -- it "exists" on PATH
      # but cannot run a script, and its failure message names the Store
      # rather than the real problem.
      if "$candidate" -c "import sys; sys.exit(0)" >/dev/null 2>&1; then
        printf '%s\n' "$candidate"
        return 0
      fi
    fi
  done
  return 1
}

INTERPRETER="$(find_usable_python || true)"
if [ -z "$INTERPRETER" ]; then
  echo "ERROR: no usable Python interpreter found on PATH ('python3' or 'python')." >&2
  echo "  Expected: Python 3.11 or newer, used to run scripts/sync-flutter-client.py." >&2
  echo "  Fix: install Python 3.11+ and make sure 'python3' (or 'python') resolves, then re-run this script." >&2
  exit 1
fi

# 'set -e' would abort before this wrapper could propagate the real code, so
# the status is captured explicitly and re-raised.
status=0
"$INTERPRETER" "$SCRIPT_DIR/sync-flutter-client.py" "$@" || status=$?
exit "$status"
